{{-- Presentation-only sample overview. Root supplies filtered fictional data and navigation callbacks. --}}
<style>
.eed{color:var(--ink,#233d32);display:grid;gap:22px;min-width:0}.eed *{box-sizing:border-box}.eed-hero{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(220px,1fr);gap:24px;padding:28px;border:1px solid #d6dfca;border-radius:10px;background:linear-gradient(120deg,#eaf0e1,#f9fbf5)}.eed-kicker{color:#596a48;font:600 10px/1.6 system-ui,sans-serif;letter-spacing:.13em;text-transform:uppercase}.eed h2{font:400 32px/1.18 Georgia,serif;letter-spacing:-.5px;margin:8px 0 12px}.eed h3{font:600 15px/1.5 system-ui,sans-serif;margin:0 0 8px}.eed h4{font:600 14px/1.5 system-ui,sans-serif;margin:0}.eed p{font:12px/1.8 system-ui,sans-serif;margin:6px 0;color:#53654c}.eed-meta{align-self:start;padding:18px;border:1px solid #d4ddc9;border-radius:8px;background:#ffffffc9;overflow-wrap:anywhere}.eed-meta strong{display:block;font:600 15px/1.5 system-ui,sans-serif}.eed-tag{display:inline-flex;gap:6px;align-items:center;padding:5px 8px;border:1px solid #c8d3ba;border-radius:4px;font:600 10px/1.5 system-ui,sans-serif;color:#3c593d;background:#f4f7ee}.eed-note{padding:13px 16px;border-left:3px solid #af8b43;background:#fbf6e8;color:#5d593d;font:12px/1.8 system-ui,sans-serif}.eed-section-head{display:flex;justify-content:space-between;align-items:flex-end;gap:14px}.eed-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.eed-card{min-width:0;padding:20px;border:1px solid var(--line,#dce3d3);border-radius:8px;background:white;text-align:left;overflow-wrap:anywhere;color:inherit}.eed-card-button{width:100%;cursor:pointer;transition:border-color .15s,box-shadow .15s}.eed-card-button:hover{border-color:#9cac87;box-shadow:0 5px 18px #25462a0b}.eed-card-button:disabled{cursor:default;opacity:1}.eed-value{display:block;font:500 30px/1.4 system-ui,sans-serif;margin:11px 0 6px;color:#244d3d}.eed-empty-value{font-size:20px;color:#68765e}.eed-metric-label{font:600 11px/1.6 system-ui,sans-serif;color:#65735b}.eed-action{display:flex;align-items:center;gap:7px;min-height:44px;font:600 11px/1.5 system-ui,sans-serif;color:#315d3e;margin-top:8px}.eed-action svg,.eed-icon svg{width:19px;height:19px;stroke:currentColor;fill:none;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round;flex-shrink:0}.eed-icon{width:38px;height:38px;display:grid;place-items:center;border-radius:8px;background:#eef3e8;color:#456642;flex-shrink:0}.eed-workspace-head{display:flex;gap:12px;align-items:flex-start;margin-bottom:13px}.eed-network{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.eed-state{display:inline-flex;align-items:center;gap:6px;font:600 10px/1.5 system-ui,sans-serif;padding:4px 7px;border-radius:4px;border:1px solid #ccd6c1;background:#eef3e8;color:#3e5e3c}.eed-state[data-state=Onboarding]{background:#fbf3df;border-color:#e1d4af;color:#75602d}.eed-state[data-state=Planned],.eed-state[data-state=Unconfirmed]{background:#f2f3ee;border-color:#d7dbcf;color:#606e56}.eed-dot{width:6px;height:6px;border-radius:50%;background:currentColor}.eed-plans{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.eed-plan{border-top:3px solid #ba9a54}.eed-plan-amount{display:block;font:400 30px/1.4 Georgia,serif;color:#244d3d;margin:12px 0}.eed-sources{display:flex;gap:8px;flex-wrap:wrap}.eed-source{display:inline-flex;align-items:center;gap:7px;min-height:44px;max-width:100%;padding:9px 12px;border:1px solid #d2dcc7;border-radius:6px;background:#f9fbf5;color:#3d583e;font:11px/1.5 system-ui,sans-serif;overflow-wrap:anywhere;text-decoration:none}.eed-source:hover{text-decoration:underline}.eed small{font:11px/1.7 system-ui,sans-serif;color:#66765b}.eed-status{font:12px/1.8 system-ui,sans-serif;min-height:1.8em}.eed :focus-visible{outline:3px solid #a17f35;outline-offset:3px}.eed button{font-family:inherit}.eed-title-row{display:flex;align-items:center;gap:10px}.eed-unavailable{font:12px/1.8 system-ui,sans-serif;padding:20px;border:1px dashed #c5d0b8;border-radius:8px;background:#f8faf4}@media(max-width:1150px){.eed-hero{grid-template-columns:1fr}.eed-plans{grid-template-columns:1fr}.eed-plan{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);column-gap:18px}.eed-plan-amount{grid-column:2;grid-row:1 / span 2;margin:0;text-align:right}.eed-plan>p{grid-column:1/-1}}@media(max-width:760px){.eed-metrics{grid-template-columns:1fr}.eed-network{grid-template-columns:1fr}.eed-section-head{display:block}.eed-hero{padding:22px}.eed h2{font-size:29px}.eed-card{padding:18px}}@media(prefers-reduced-motion:reduce){.eed-card-button{transition:none}}
</style>
